WITH imported AS (
  SELECT
    json_extract(value, '$."Slug"') AS slug,
    json_extract(value, '$."Názov klubu"') AS name,
    json_extract(value, '$."Popis"') AS description,
    CASE WHEN json_extract(value, '$."Zameranie"') IS NULL THEN '[]' ELSE json_array(json_extract(value, '$."Zameranie"')) END AS services_json,
    CASE WHEN json_extract(value, '$."Organizácia"') IS NULL THEN '[]' ELSE json_array(json_extract(value, '$."Organizácia"')) END AS qualifications_json,
    json_extract(value, '$."Mesto / obec"') AS city,
    json_extract(value, '$."Kraj"') AS region,
    coalesce(json_extract(value, '$."Adresa / cvičisko"'), '') AS address,
    json_extract(value, '$."Web"') AS website_url,
    CASE WHEN json_extract(value, '$."E-mail"') IS NULL THEN NULL WHEN instr(json_extract(value, '$."E-mail"'), ';') > 0 THEN trim(substr(json_extract(value, '$."E-mail"'), 1, instr(json_extract(value, '$."E-mail"'), ';') - 1)) ELSE trim(json_extract(value, '$."E-mail"')) END AS internal_email,
    json_extract(value, '$."Import key"') AS import_key,
    json(value) AS source_data_json,
    CASE WHEN json_extract(value, '$."Stav"') = 'Overené' THEN 1 ELSE 0 END AS verified,
    json_extract(value, '$."Dátum overenia"') || 'T00:00:00.000Z' AS imported_at
  FROM `_kynologicke_kluby_import_seed`, json_each(`payload`)
)
UPDATE `directory_profiles` AS profile SET
  `slug` = imported.slug, `name` = imported.name, `category` = 'kynologicke-kluby', `status` = 'published',
  `excerpt` = imported.description, `description` = imported.description, `services_json` = imported.services_json,
  `qualifications_json` = imported.qualifications_json, `city` = imported.city, `region` = imported.region,
  `address` = imported.address, `online` = 0, `price_note` = '', `website_url` = imported.website_url,
  `internal_email` = imported.internal_email, `import_key` = imported.import_key, `source_data_json` = imported.source_data_json,
  `verified` = imported.verified, `updated_at` = imported.imported_at, `published_at` = coalesce(profile.published_at, imported.imported_at),
  `updated_by` = 'import:kynologicke-kluby'
FROM imported
WHERE profile.import_key = imported.import_key OR (profile.import_key IS NULL AND profile.category = 'kynologicke-kluby' AND profile.slug = imported.slug);--> statement-breakpoint
