INSERT INTO `directory_profiles` (
  `slug`, `name`, `category`, `status`, `excerpt`, `description`, `services_json`, `qualifications_json`,
  `city`, `region`, `address`, `online`, `price_note`, `website_url`, `internal_email`, `image_url`, `image_key`,
  `import_key`, `source_data_json`, `verified`, `featured`, `created_at`, `updated_at`, `published_at`, `created_by`, `updated_by`
)
SELECT imported.slug, imported.name, 'kynologicke-kluby', 'published', imported.description, imported.description, imported.services_json, imported.qualifications_json,
  imported.city, imported.region, imported.address, 0, '', imported.website_url, imported.internal_email, NULL, NULL,
  imported.import_key, imported.source_data_json, imported.verified, 0, imported.imported_at, imported.imported_at, imported.imported_at,
